sql.where:
a.delete_flag = 'N'
AND a.enable_flag = 'Y'
AND a.tenantid = #{tenantid}

    AND EXISTS (
        SELECT 1 FROM fdc_application_detail_t d
        WHERE d.application_id = a.application_id
          AND d.delete_flag = 'N' AND d.enable_flag = 'Y' AND d.tenantid = #{tenantid}
          AND d.company_project_code = #{f.companyProjectCode}
    )


    AND a.applicant = #{f.applicant}


    AND a.application_number LIKE CONCAT('%', #{f.applicationNumber}, '%')


    AND a.application_date >= #{f.applicationDateStart}


    AND a.application_date <= #{f.applicationDateEnd}


    AND a.application_status = #{f.applicationStatus}


    AND a.carrier_type = #{f.carrierType}


    AND a.diff_reason_code = #{f.diffReasonCode}


    AND a.apply_method = #{f.applyMethod}


    AND a.express_type = #{f.expressType}


    AND a.express_number LIKE CONCAT('%', #{f.expressNumber}, '%')


    AND a.document_recipient = #{f.documentRecipient}


    AND EXISTS (
        SELECT 1 FROM fdc_application_detail_t d
        WHERE d.application_id = a.application_id
          AND d.delete_flag = 'N' AND d.enable_flag = 'Y' AND d.tenantid = #{tenantid}
          AND d.doc_busi_no LIKE CONCAT('%', #{f.docBusiNo}, '%')
    )


    AND EXISTS (
        SELECT 1 FROM fdc_application_detail_t d
        WHERE d.application_id = a.application_id
          AND d.delete_flag = 'N' AND d.enable_flag = 'Y' AND d.tenantid = #{tenantid}
          AND d.busi_module_code = #{f.busiModuleCode}
    )


    AND EXISTS (
        SELECT 1 FROM fdc_application_detail_t d
        WHERE d.application_id = a.application_id
          AND d.delete_flag = 'N' AND d.enable_flag = 'Y' AND d.tenantid = #{tenantid}
          AND (d.start_arch_period IS NULL OR d.start_arch_period <= #{f.archPeriodEnd})
          AND (d.end_arch_period IS NULL OR d.end_arch_period >= #{f.archPeriodStart})
    )


    AND EXISTS (
        SELECT 1 FROM fdc_application_detail_t d
        WHERE d.application_id = a.application_id
          AND d.delete_flag = 'N' AND d.enable_flag = 'Y' AND d.tenantid = #{tenantid}
          AND d.catalog_volume_no LIKE CONCAT('%', #{f.catalogVolumeNo}, '%')
    )
